# connected same-color components, 4-neighbor
from collections import deque
seen=set(); comps=[]
for r in range(12):
 for c in range(30):
  col=a[r][c]
  if col!=0 and (r,c) not in seen:
   q=deque([(r,c)]); seen.add((r,c)); cells=[]
   while q:
    p=q.popleft(); cells.append(p)
    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
     nr,nc=p[0]+dr,p[1]+dc
     if 0<=nr<12 and 0<=nc<30 and a[nr][nc]==col and (nr,nc) not in seen:
      seen.add((nr,nc)); q.append((nr,nc))
   comps.append((col,min(r for r,c in cells),max(r for r,c in cells),min(c for r,c in cells),max(c for r,c in cells),len(cells)))
print(comps)
